SELECT 'printings' AS scope,id::text AS identity,to_jsonb(t) AS payload FROM catalog.card_printings t WHERE id=ANY(ARRAY['9884a2e7-1d5d-4355-99c5-0fe2556c4837','5a6e6094-b847-4e50-bfb5-f8dec149e07e']::uuid[]) UNION ALL SELECT 'variants',id::text,to_jsonb(t) FROM catalog.card_variants t WHERE printing_id=ANY(ARRAY['9884a2e7-1d5d-4355-99c5-0fe2556c4837','5a6e6094-b847-4e50-bfb5-f8dec149e07e']::uuid[]) UNION ALL SELECT 'names',id::text,to_jsonb(t) FROM catalog.card_names t WHERE printing_id=ANY(ARRAY['9884a2e7-1d5d-4355-99c5-0fe2556c4837','5a6e6094-b847-4e50-bfb5-f8dec149e07e']::uuid[]) OR variant_id=ANY(ARRAY['00dbf2d3-a5cb-4e83-83bd-4eeef011d6bc','1fc97b9f-48eb-4be8-a29c-cd1844bc2757','6a922068-873d-46d8-b5d8-5539df9ce8a1','942e0c49-1234-4c4f-9af4-53bc522bade9']::uuid[]) UNION ALL SELECT 'sets',id::text,to_jsonb(t) FROM catalog.sets t WHERE id=ANY(ARRAY['2cd06c25-7efb-442d-b1ff-8f00979d5fe4']::uuid[]) UNION ALL SELECT 'sources',id::text,to_jsonb(t) FROM ingest.sources t WHERE (code IN ('scrydex','pokellector','tcgcollector','pricecharting') OR lower(base_url) LIKE '%pokellector.com%' OR lower(base_url) LIKE '%tcgcollector.com%' OR lower(base_url) LIKE '%pricecharting.com%') UNION ALL SELECT 'assets',id::text,to_jsonb(t) FROM catalog.assets t WHERE printing_id=ANY(ARRAY['9884a2e7-1d5d-4355-99c5-0fe2556c4837','5a6e6094-b847-4e50-bfb5-f8dec149e07e']::uuid[]) OR variant_id=ANY(ARRAY['00dbf2d3-a5cb-4e83-83bd-4eeef011d6bc','1fc97b9f-48eb-4be8-a29c-cd1844bc2757','6a922068-873d-46d8-b5d8-5539df9ce8a1','942e0c49-1234-4c4f-9af4-53bc522bade9']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['2cd06c25-7efb-442d-b1ff-8f00979d5fe4']::uuid[])) UNION ALL SELECT 'links',catalogue_version_id::text||':'||asset_id::text,to_jsonb(t) FROM catalog.catalogue_version_assets t WHERE printing_id=ANY(ARRAY['9884a2e7-1d5d-4355-99c5-0fe2556c4837','5a6e6094-b847-4e50-bfb5-f8dec149e07e']::uuid[]) OR variant_id=ANY(ARRAY['00dbf2d3-a5cb-4e83-83bd-4eeef011d6bc','1fc97b9f-48eb-4be8-a29c-cd1844bc2757','6a922068-873d-46d8-b5d8-5539df9ce8a1','942e0c49-1234-4c4f-9af4-53bc522bade9']::uuid[]) OR asset_id IN(SELECT id FROM catalog.assets WHERE printing_id=ANY(ARRAY['9884a2e7-1d5d-4355-99c5-0fe2556c4837','5a6e6094-b847-4e50-bfb5-f8dec149e07e']::uuid[]) OR variant_id=ANY(ARRAY['00dbf2d3-a5cb-4e83-83bd-4eeef011d6bc','1fc97b9f-48eb-4be8-a29c-cd1844bc2757','6a922068-873d-46d8-b5d8-5539df9ce8a1','942e0c49-1234-4c4f-9af4-53bc522bade9']::uuid[]) OR (printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['2cd06c25-7efb-442d-b1ff-8f00979d5fe4']::uuid[]))) OR(printing_id IS NULL AND variant_id IS NULL AND set_id=ANY(ARRAY['2cd06c25-7efb-442d-b1ff-8f00979d5fe4']::uuid[])) ORDER BY scope,identity;